(() => {
  const STORAGE_KEY = "garden-labs-machines-v1";
  const PENDING_KEY = "garden-labs-machines-pending-v1";
  const ENDPOINT = "/api/machine-state";
  let catalog = null;
  let instances = [];
  let syncMode = "checking";
  const $ = (selector) => document.querySelector(selector);
  const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
  const lang = () => document.documentElement.lang === "en" ? "en" : "es";
  const copy = {
    es: { machines: "Máquinas", subtitle: "Hardware de cultivo que posees: especificaciones del modelo separadas de los datos y evaluación de cada unidad.", inventory: "INVENTARIO USER ZERO", onHand: "en casa", ordered: "en camino", active: "Activa", idle: "Inactiva", maintenance: "Mantenimiento", unknown: "Sin definir", retired: "Retirada", orderedStatus: "En camino", onHandStatus: "En casa", noRating: "Sin calificar", pods: "pods", positions: "posiciones", myMachine: "MI MÁQUINA", myUnit: "Mi unidad", ownership: "Propiedad", operation: "Operación", purchaseDate: "Fecha de compra", seller: "Lugar / vendedor", channel: "Canal", price: "Precio pagado (USD)", received: "Fecha recibida", firstUse: "Primer uso", location: "Ubicación", evaluation: "Mi evaluación", overall: "Overall Rating", buyAgain: "¿La comprarías otra vez?", notes: "Notas", specs: "Especificaciones del modelo", tank: "Tanque", color: "Color", light: "Luz", save: "Guardar cambios", online: "Online", physical: "Tienda física", yes: "Sí", maybe: "Quizás", no: "No", synced: "Estado personal · sincronizado en almacenamiento privado", local: "Sin sincronización · guardado en este dispositivo", checking: "Conectando almacenamiento…", modelSource: "Fuente del modelo" },
    en: { machines: "Machines", subtitle: "Growing hardware you own: model specifications kept separate from each unit's personal data and evaluation.", inventory: "USER ZERO INVENTORY", onHand: "on hand", ordered: "ordered", active: "Active", idle: "Idle", maintenance: "Maintenance", unknown: "Not set", retired: "Retired", orderedStatus: "Ordered", onHandStatus: "On hand", noRating: "Not rated", pods: "pods", positions: "positions", myMachine: "MY MACHINE", myUnit: "My unit", ownership: "Ownership", operation: "Operation", purchaseDate: "Purchase date", seller: "Seller / place", channel: "Channel", price: "Price paid (USD)", received: "Received date", firstUse: "First use", location: "Location", evaluation: "My rating", overall: "Overall Rating", buyAgain: "Would buy again?", notes: "Notes", specs: "Model Specs", tank: "Tank", color: "Color", light: "Lighting", save: "Save changes", online: "Online", physical: "Physical store", yes: "Yes", maybe: "Maybe", no: "No", synced: "Personal state · synced in private storage", local: "Sync unavailable · saved on this device", checking: "Connecting storage…", modelSource: "Model source" }
  };
  function safeRead(key, fallback) { try { return JSON.parse(localStorage.getItem(key) || "null") ?? fallback; } catch { return fallback; } }
  function persistLocal() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(instances)); } catch {} }
  function model(instance) { return catalog.models.find((item) => item.id === instance.modelId); }
  function ownershipLabel(value) { const t = copy[lang()]; return value === "ordered" ? t.orderedStatus : value === "retired" ? t.retired : t.onHandStatus; }
  function operationLabel(value) { const t = copy[lang()]; return ({ active:t.active, idle:t.idle, maintenance:t.maintenance, unknown:t.unknown, retired:t.retired, "n/a":"N/A" })[value] || t.unknown; }
  function stars(value) { return value ? `★ ${Number(value).toFixed(1)}` : copy[lang()].noRating; }
  function setMachineView(on) {
    const ms=$("#machinesSurface"), gs=$("#guideSurface"), ss=$("#seedsSurface"), mt=$("#machinesTab"), gt=$("#guideTab"), st=$("#seedsTab"); if(!ms) return;
    ms.hidden=!on;
    if(on){ gs.hidden=true; ss.hidden=true; mt.classList.add("active"); mt.setAttribute("aria-pressed","true"); [gt,st].forEach(x=>{x.classList.remove("active");x.setAttribute("aria-pressed","false")}); localStorage.setItem("gardenLabsLibraryView","machines"); updateHeader(); render(); }
    else { mt.classList.remove("active"); mt.setAttribute("aria-pressed","false"); }
  }
  function updateHeader(){ if(localStorage.getItem("gardenLabsLibraryView")!=="machines") return; const t=copy[lang()]; $("#productEyebrow").textContent="GARDEN LABS · MACHINES"; $("#productTitle").textContent=t.machines; const intro=$("#machinesSurface .surface-intro p:last-child"); if(intro) intro.textContent=t.subtitle; const eyebrow=$("#machinesSurface .seed-section-heading .eyebrow"); if(eyebrow) eyebrow.textContent=t.inventory; const note=$("#machineStorageNote"); if(note) note.textContent=t[syncMode] || t.local; }
  function bindNav(){ $("#machinesTab")?.addEventListener("click",()=>setMachineView(true)); ["#guideTab","#seedsTab"].forEach(s=>$(s)?.addEventListener("click",()=>setMachineView(false))); document.querySelectorAll("[data-language]").forEach(b=>b.addEventListener("click",()=>setTimeout(()=>{updateHeader();render()},0))); if(localStorage.getItem("gardenLabsLibraryView")==="machines") setMachineView(true); }
  async function post(payload){ const response=await fetch(ENDPOINT,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload),cache:"no-store"}); if(!response.ok) throw new Error(`machine storage ${response.status}`); return response.json(); }
  async function hydrate(){
    const local=safeRead(STORAGE_KEY, null); if(Array.isArray(local)) instances=local;
    try{
      const response=await fetch(ENDPOINT,{cache:"no-store"}); if(!response.ok) throw new Error("machine storage unavailable"); const remote=await response.json();
      if(Array.isArray(remote.instances) && remote.instances.length){ const byId=Object.fromEntries(instances.map(i=>[i.id,i])); remote.instances.forEach(r=>{ if(byId[r.id]) Object.assign(byId[r.id],r); }); instances=Object.values(byId); }
      syncMode="synced";
      const pending=safeRead(PENDING_KEY,[]); const remaining=[]; for(const operation of pending){ try{await post(operation)}catch{remaining.push(operation)} } localStorage.setItem(PENDING_KEY,JSON.stringify(remaining)); if(remaining.length) syncMode="local";
    }catch(error){ console.warn("Machines private storage unavailable; using local cache",error); syncMode="local"; }
    persistLocal(); updateHeader(); render();
  }
  async function saveInstance(instance){ persistLocal(); const operation={operation:"save",instance}; try{await post(operation);syncMode="synced";}catch(error){console.warn("Machine saved locally; private sync pending",error);syncMode="local";const pending=safeRead(PENDING_KEY,[]).filter(x=>x.instance?.id!==instance.id);pending.push(operation);localStorage.setItem(PENDING_KEY,JSON.stringify(pending));} updateHeader(); render(); }
  async function load(){ catalog=await fetch("./data/machine-inventory-v1.json").then(r=>r.json()); instances=structuredClone(catalog.instances); bindNav(); await hydrate(); }
  function render(){
    const grid=$("#machineGrid"); if(!grid||!catalog)return; const t=copy[lang()]; const totalPods=catalog.models.reduce((a,m)=>a+m.pods,0); const onHand=instances.filter(i=>i.ownershipStatus==="on_hand").length; const ordered=instances.filter(i=>i.ownershipStatus==="ordered").length;
    $("#machineResultCount").textContent=`${instances.length} ${t.machines.toLowerCase()} · ${totalPods} ${t.positions} · ${onHand} ${t.onHand} · ${ordered} ${t.ordered}`;
    grid.innerHTML=instances.map(i=>{const m=model(i);return `<article class="machine-card"><button class="machine-card-button" data-machine="${esc(i.id)}"><div class="machine-photo machine-${esc(m.color)}"><span>${esc(m.brand)}</span><strong>${m.pods}</strong><small>PODS</small></div><div><p class="machine-brand">${esc(m.brand)}</p><h4>${esc(m.name)}</h4><p class="muted">${esc(m.model)}</p></div><div class="machine-card-meta"><span>${m.pods} ${t.pods}</span><span class="machine-status ${esc(i.ownershipStatus)}">${esc(ownershipLabel(i.ownershipStatus))}</span><span>${esc(operationLabel(i.operationalStatus))}</span><span>${esc(stars(i.overallRating))}</span></div></button></article>`}).join(""); grid.querySelectorAll("[data-machine]").forEach(b=>b.onclick=()=>open(b.dataset.machine));
  }
  function options(values, selected, labels={}){return values.map(v=>`<option value="${esc(v)}" ${selected===v?"selected":""}>${esc(labels[v]||v)}</option>`).join("")}
  function open(id){
    const i=instances.find(x=>x.id===id),m=model(i),d=$("#machineDetail"),t=copy[lang()];
    const tank=typeof m.tankLiters==="object"?`${m.tankLiters.min}–${m.tankLiters.max}`:m.tankLiters;
    d.innerHTML=`<div class="machine-detail-head"><div class="machine-photo machine-${esc(m.color)}"><span>${esc(m.brand)}</span><strong>${m.pods}</strong><small>PODS</small></div><div><p class="eyebrow">${t.myMachine}</p><h2>${esc(m.name)}</h2><p>${esc(m.model)} · ${m.pods} ${t.pods}</p></div></div><form id="machineForm"><h3>${t.myUnit}</h3><div class="machine-form-grid"><label>${t.ownership}<select name="ownershipStatus">${options(["on_hand","ordered","retired"],i.ownershipStatus,{on_hand:t.onHandStatus,ordered:t.orderedStatus,retired:t.retired})}</select></label><label>${t.operation}<select name="operationalStatus">${options(["active","idle","maintenance","unknown","retired","n/a"],i.operationalStatus,{active:t.active,idle:t.idle,maintenance:t.maintenance,unknown:t.unknown,retired:t.retired,"n/a":"N/A"})}</select></label><label>${t.purchaseDate}<input type="date" name="purchaseDate" value="${esc(i.purchase?.date||"")}"></label><label>${t.seller}<input name="seller" value="${esc(i.purchase?.seller||"")}"></label><label>${t.channel}<select name="channel"><option value="">—</option>${options(["online","physical_store"],i.purchase?.channel||"",{online:t.online,physical_store:t.physical})}</select></label><label>${t.price}<input type="number" step="0.01" min="0" name="price" value="${i.purchase?.priceUsd??""}"></label><label>${t.received}<input type="date" name="receivedDate" value="${esc(i.receivedDate||"")}"></label><label>${t.firstUse}<input type="date" name="firstUseDate" value="${esc(i.firstUseDate||"")}"></label><label>${t.location}<input name="location" value="${esc(i.location||"")}"></label></div><h3>${t.evaluation}</h3><div class="rating-grid">${catalog.ratingDimensions.map(r=>`<label>${esc(r[lang()]||r.en)}<select name="rating-${r.id}"><option value="">—</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${i.ratings?.[r.id]==n?"selected":""}>${"★".repeat(n)} (${n})</option>`).join("")}</select></label>`).join("")}</div><div class="machine-form-grid"><label>${t.overall}<select name="overall"><option value="">—</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${i.overallRating==n?"selected":""}>${"★".repeat(n)} (${n})</option>`).join("")}</select></label><label>${t.buyAgain}<select name="buyAgain"><option value="">—</option>${options(["yes","maybe","no"],i.wouldBuyAgain||"",{yes:t.yes,maybe:t.maybe,no:t.no})}</select></label></div><label>${t.notes}<textarea name="notes" rows="3">${esc(i.notes||"")}</textarea></label><h3>${t.specs}</h3><div class="machine-specs"><span><b>${t.tank}</b> ${tank} L</span><span><b>${t.color}</b> ${esc(m.color)}</span><span><b>Pods</b> ${m.pods}</span><span><b>${t.light}</b> ${m.light.watts?m.light.watts+"W · ":""}${m.light.modes?m.light.modes.join(" / "):"Auto timer"}</span></div><p class="machine-source"><a href="${esc(m.referenceUrl||m.purchaseUrl)}" target="_blank" rel="noreferrer">${t.modelSource} ↗</a></p><div class="machine-form-actions"><button type="submit" class="lab-primary-button">${t.save}</button></div></form>`;
    $("#machineForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);i.ownershipStatus=String(f.get("ownershipStatus"));i.operationalStatus=String(f.get("operationalStatus"));i.purchase={date:f.get("purchaseDate")||null,seller:f.get("seller")||null,channel:f.get("channel")||null,priceUsd:f.get("price")?Number(f.get("price")):null};i.receivedDate=f.get("receivedDate")||null;i.firstUseDate=f.get("firstUseDate")||null;i.location=String(f.get("location")||"").trim()||null;i.notes=String(f.get("notes")||"").trim();i.ratings=i.ratings||{};catalog.ratingDimensions.forEach(r=>{const v=f.get(`rating-${r.id}`);if(v)i.ratings[r.id]=Number(v);else delete i.ratings[r.id]});i.overallRating=f.get("overall")?Number(f.get("overall")):null;i.wouldBuyAgain=f.get("buyAgain")||null;await saveInstance(i);$("#machineDialog").close();}; $("#machineDialog").showModal();
  }
  window.GardenMachinesV1={load,render}; document.addEventListener("DOMContentLoaded",load);
})();
